[CmdletBinding()]
param(
    [switch]$Install,
    [switch]$Uninstall,
    [switch]$AutoHeal,
    [switch]$Silent,
    [switch]$NoRestart,
    [switch]$PauseAtEnd
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8

$backupDir = Join-Path ([System.IO.Path]::GetTempPath()) "claude-zh-tw-backup"
$utf8NoBom = [System.Text.UTF8Encoding]::new($false)

# 內嵌臺灣正體中文壓縮資料庫 (Gzip + Base64，提供單檔免外部依賴獨立運作能力)
$B64_DESKTOP = ""

$B64_STATSIG = ""

$B64_ION = ""

function Test-IsAdministrator {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = [Security.Principal.WindowsPrincipal]::new($identity)
    return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

function Ensure-Administrator {
    param([string[]]$Arguments = @())

    if (Test-IsAdministrator) {
        return
    }

    $argumentList = @(
        "-NoProfile",
        "-ExecutionPolicy",
        "Bypass",
        "-File",
        "`"$PSCommandPath`""
    ) + $Arguments

    if ($Silent -or $AutoHeal) {
        try {
            $proc = Start-Process -FilePath "powershell.exe" -Verb RunAs -ArgumentList $argumentList -WindowStyle Hidden -PassThru -ErrorAction Stop
            if ($proc) { $proc.WaitForExit() }
            exit 0
        } catch {
            return
        }
    } else {
        try {
            $proc = Start-Process -FilePath "powershell.exe" -Verb RunAs -ArgumentList $argumentList -PassThru -ErrorAction Stop
            exit 0
        } catch {
            Write-Host "  [提示] 無法自動喚起 UAC 系統管理員提權視窗 ($($_.Exception.Message))" -ForegroundColor Yellow
            Write-Host "  若安裝過程出現權限不足，請以滑鼠右鍵點選「以系統管理員身分執行」。" -ForegroundColor Yellow
            Write-Host ""
            return
        }
    }
}

function Wait-BeforeExit {
    if ($Silent -or $AutoHeal) { return }
    Write-Host ""
    [void](Read-Host "請按 Enter 鍵關閉視窗")
}

function Write-Utf8File {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$Content
    )
    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        [System.IO.Directory]::CreateDirectory($parent) | Out-Null
    }
    [System.IO.File]::WriteAllText($Path, $Content, $utf8NoBom)
}

function Decompress-B64GzToFile {
    param(
        [Parameter(Mandatory = $true)][string]$Base64,
        [Parameter(Mandatory = $true)][string]$OutPath
    )
    $parent = Split-Path -Parent $OutPath
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        [System.IO.Directory]::CreateDirectory($parent) | Out-Null
    }
    $bytes = [System.Convert]::FromBase64String($Base64)
    $ms = [System.IO.MemoryStream]::new($bytes)
    $gz = [System.IO.Compression.GzipStream]::new($ms, [System.IO.Compression.CompressionMode]::Decompress)
    $fs = [System.IO.File]::Create($OutPath)
    $gz.CopyTo($fs)
    $fs.Close()
    $gz.Close()
    $ms.Close()
}

function Find-ClaudePath {
    # 1. 優先查詢 Windows Store / MSIX 封裝版本
    try {
        $pkg = Get-AppxPackage -Name Claude -ErrorAction Stop |
            Sort-Object Version -Descending |
            Select-Object -First 1
        if ($pkg -and $pkg.InstallLocation -and (Test-Path -LiteralPath $pkg.InstallLocation)) {
            return $pkg.InstallLocation
        }
    } catch {}

    # 2. 查詢 Appx 註冊表部署目錄
    try {
        $deployments = Get-ChildItem "HKLM:\Software\Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore\Deployments" -ErrorAction Stop |
            Where-Object { $_.PSChildName -like "Claude*" } |
            Sort-Object PSChildName -Descending
        foreach ($deployment in $deployments) {
            $candidate = Join-Path ${env:ProgramFiles} "WindowsApps\$($deployment.PSChildName)"
            if (Test-Path -LiteralPath $candidate) {
                return $candidate
            }
        }
    } catch {}

    # 3. 掃描 WindowsApps 系統目錄
    $windowsApps = Join-Path ${env:ProgramFiles} "WindowsApps"
    if (Test-Path -LiteralPath $windowsApps) {
        $candidate = Get-ChildItem -LiteralPath $windowsApps -Directory -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -like "Claude*" } |
            Sort-Object Name -Descending |
            Select-Object -First 1
        if ($candidate) {
            return $candidate.FullName
        }
    }

    # 4. 掃描 LocalAppData Squirrel / 一般桌面版本
    $localClaude = Join-Path ${env:LOCALAPPDATA} "Programs\Claude"
    if (Test-Path -LiteralPath $localClaude) {
        return $localClaude
    }

    return $null
}

function Get-ResourcesPath {
    param([Parameter(Mandatory = $true)][string]$ClaudePath)
    $resourcesPath = Join-Path $ClaudePath "app\resources"
    if (Test-Path -LiteralPath $resourcesPath) {
        return $resourcesPath
    }
    $resourcesDirect = Join-Path $ClaudePath "resources"
    if (Test-Path -LiteralPath $resourcesDirect) {
        return $resourcesDirect
    }
    return $null
}

function Grant-WriteAccess {
    param([Parameter(Mandatory = $true)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) {
        return
    }
    $item = Get-Item -LiteralPath $Path -ErrorAction Stop
    $takeownArgs = @("/f", $Path, "/a")
    if ($item.PSIsContainer) {
        $takeownArgs += @("/r", "/d", "Y")
    }
    $takeownOutput = & takeown.exe @takeownArgs 2>&1
    if ($LASTEXITCODE -ne 0) {
        throw "無法取得寫入權限 (takeown 失敗): $Path`n$($takeownOutput -join "`n")"
    }

    $identity = [Security.Principal.WindowsIdentity]::GetCurrent().Name
    if (-not $identity) {
        throw "無法確定目前 Windows 使用者，無法授予寫入權限: $Path"
    }

    $icaclsArgs = @($Path, "/grant", "${identity}:F")
    if ($item.PSIsContainer) {
        $icaclsArgs += @("/t", "/c")
    }
    $icaclsOutput = & icacls.exe @icaclsArgs 2>&1
    if ($LASTEXITCODE -ne 0) {
        throw "無法授予寫入權限 (icacls 失敗): $Path`n$($icaclsOutput -join "`n")"
    }

    if ($item.PSIsContainer) {
        $inheritOutput = & icacls.exe $Path "/grant" "${identity}:(OI)(CI)F" 2>&1
        if ($LASTEXITCODE -ne 0) {
            throw "無法設定目錄權限繼承 (icacls 失敗): $Path`n$($inheritOutput -join "`n")"
        }
    }

    $attribArgs = @("-R", $Path)
    if ($item.PSIsContainer) {
        $attribArgs += @("/S", "/D")
    }
    $attribOutput = & attrib.exe @attribArgs 2>&1
    if ($LASTEXITCODE -ne 0) {
        throw "無法移除唯讀屬性 (attrib 失敗): $Path`n$($attribOutput -join "`n")"
    }
}

function Backup-File {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $false)][string]$RelativeTo = ""
    )
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        return
    }
    if ($RelativeTo -and $Path.StartsWith($RelativeTo, [System.StringComparison]::OrdinalIgnoreCase)) {
        $relative = $Path.Substring($RelativeTo.Length).TrimStart("\")
    } else {
        $relative = Split-Path $Path -Leaf
    }
    $destination = Join-Path $backupDir $relative
    $destFolder = Split-Path -Parent $destination
    if (-not (Test-Path -LiteralPath $destFolder)) {
        [System.IO.Directory]::CreateDirectory($destFolder) | Out-Null
    }
    if (-not (Test-Path -LiteralPath $destination -PathType Leaf)) {
        Copy-Item -LiteralPath $Path -Destination $destination -Force
    }
}

function Get-BackupPath {
    param(
        [Parameter(Mandatory = $true)][string]$OriginalPath,
        [Parameter(Mandatory = $false)][string]$RelativeTo = ""
    )
    if ($RelativeTo -and $OriginalPath.StartsWith($RelativeTo, [System.StringComparison]::OrdinalIgnoreCase)) {
        $relative = $OriginalPath.Substring($RelativeTo.Length).TrimStart("\")
    } else {
        $relative = Split-Path $OriginalPath -Leaf
    }
    return (Join-Path $backupDir $relative)
}

function Patch-JsLanguage {
    param(
        [Parameter(Mandatory = $true)][string]$ResourcesPath,
        [switch]$Silent
    )
    $assetsDir = Join-Path $ResourcesPath "ion-dist\assets\v1"
    if (-not (Test-Path -LiteralPath $assetsDir -PathType Container)) {
        if (-not $Silent) { Write-Host "  [警告] 找不到 assets 目錄，跳過 JS 補丁" -ForegroundColor Yellow }
        return $false
    }

    $jsFiles = Get-ChildItem -LiteralPath $assetsDir -Filter "*.js" -File -ErrorAction SilentlyContinue
    if (-not $jsFiles) {
        if (-not $Silent) { Write-Host "  [警告] 找不到 JS 檔案，跳過 JS 補丁" -ForegroundColor Yellow }
        return $false
    }

    $regexAdd = [regex]'((?:[\w$]+)=\["en-US"(?:,"[^"]+")+)\]'
    $patched = $false

    foreach ($jsFile in $jsFiles) {
        Grant-WriteAccess -Path $jsFile.FullName
        $content = [System.IO.File]::ReadAllText($jsFile.FullName)
        if ($content.Contains('"zh-TW"')) {
            if (-not $Silent) { Write-Host "  已註冊語言: $($jsFile.Name)" -ForegroundColor DarkGray }
            $patched = $true
            continue
        }

        $newContent = $regexAdd.Replace($content, '$1,"zh-TW"]', 1)
        if ($newContent -ne $content) {
            Backup-File -Path $jsFile.FullName -RelativeTo $ResourcesPath
            Write-Utf8File -Path $jsFile.FullName -Content $newContent
            if (-not $Silent) { Write-Host "  JS 語言白名單已修補: $($jsFile.Name)" -ForegroundColor Green }
            $patched = $true
            continue
        }
    }
    return $patched
}

function Unpatch-JsLanguage {
    param([Parameter(Mandatory = $true)][string]$ResourcesPath)
    $assetsDir = Join-Path $ResourcesPath "ion-dist\assets\v1"
    if (-not (Test-Path -LiteralPath $assetsDir -PathType Container)) {
        return
    }

    $jsFiles = Get-ChildItem -LiteralPath $assetsDir -Filter "*.js" -File -ErrorAction SilentlyContinue
    $regexRemove = [regex]'((?:[\w$]+)=\[(?:"[^"]+",)+)"zh-TW"\]'

    foreach ($jsFile in $jsFiles) {
        $backupPath = Get-BackupPath -OriginalPath $jsFile.FullName -RelativeTo $ResourcesPath
        if (Test-Path -LiteralPath $backupPath -PathType Leaf) {
            Grant-WriteAccess -Path $jsFile.FullName
            Copy-Item -LiteralPath $backupPath -Destination $jsFile.FullName -Force
            Write-Host "  從備份還原: $($jsFile.Name)" -ForegroundColor Green
            continue
        }

        Grant-WriteAccess -Path $jsFile.FullName
        $content = [System.IO.File]::ReadAllText($jsFile.FullName)
        if (-not $content.Contains('"zh-TW"')) {
            continue
        }
        $newContent = $regexRemove.Replace($content, '$1]', 1)
        if ($newContent -ne $content) {
            Write-Utf8File -Path $jsFile.FullName -Content $newContent
            Write-Host "  語言註冊已還原: $($jsFile.Name)" -ForegroundColor Green
        }
    }

    if (Test-Path -LiteralPath $backupDir -PathType Container) {
        Remove-Item -LiteralPath $backupDir -Recurse -Force -ErrorAction SilentlyContinue
    }
}

function Update-Config {
    param(
        [Parameter(Mandatory = $true)][string]$Locale,
        [switch]$Silent
    )
    $base = Join-Path ${env:LOCALAPPDATA} "Packages\Claude_pzs8sxrjxfjjc"
    $configPaths = @(
        (Join-Path $base "LocalCache\Roaming\Claude\config.json"),
        (Join-Path $base "LocalCache\Roaming\Claude-3p\config.json"),
        (Join-Path ${env:APPDATA} "Claude\config.json")
    )
    foreach ($configPath in $configPaths) {
        if (-not (Test-Path -LiteralPath $configPath -PathType Leaf)) {
            continue
        }
        try {
            $raw = Get-Content -LiteralPath $configPath -Raw -Encoding UTF8
            if ($raw -match '"locale"\s*:') {
                $newRaw = $raw -replace '("locale"\s*:\s*)"[^"]*"', "`$1`"$Locale`""
            } else {
                $newRaw = $raw -replace '(\s*)\}(\s*)$', ",`r`n  `"locale`": `"$Locale`"`$1}`$2"
            }
            Write-Utf8File -Path $configPath -Content $newRaw
            if (-not $Silent) {
                Write-Host "  偏好設定更新成功: $(Split-Path $configPath -Leaf) (語言: $Locale)" -ForegroundColor Green
            }
        } catch {
            if (-not $Silent) {
                Write-Host "  [警告] 偏好設定更新失敗: $(Split-Path $configPath -Leaf)" -ForegroundColor Yellow
            }
        }
    }
}

function Register-AutoHealTask {
    param([Parameter(Mandatory = $true)][string]$ScriptPath)
    $taskName = "Claude-zh-TW-AutoHeal"
    try {
        $arg = "-WindowStyle Hidden -ExecutionPolicy Bypass -NoProfile -File `"$ScriptPath`" -AutoHeal -Silent"
        $createOutput = & schtasks.exe /create /tn $taskName /tr "powershell.exe $arg" /sc onlogon /rl highest /f 2>&1
        if ($LASTEXITCODE -eq 0) {
            Write-Host "  已註冊自動守護排程 (小版本更新不失效): $taskName" -ForegroundColor Green
        } else {
            Write-Host "  [提示] 自動守護排程設定略過: $createOutput" -ForegroundColor DarkGray
        }
    } catch {
        Write-Host "  [提示] 自動守護排程設定略過: $($_.Exception.Message)" -ForegroundColor DarkGray
    }
}

function Unregister-AutoHealTask {
    $taskName = "Claude-zh-TW-AutoHeal"
    try {
        & schtasks.exe /delete /tn $taskName /f 2>&1 | Out-Null
        Write-Host "  已移除自動守護排程: $taskName" -ForegroundColor Green
    } catch {}
}

function Test-NeedsHeal {
    param([Parameter(Mandatory = $true)][string]$ResourcesPath)
    $i18nZhTw = Join-Path $ResourcesPath "ion-dist\i18n\zh-TW.json"
    $shellZhTw = Join-Path $ResourcesPath "zh-TW.json"
    if ((-not (Test-Path -LiteralPath $i18nZhTw -PathType Leaf)) -or (-not (Test-Path -LiteralPath $shellZhTw -PathType Leaf))) {
        return $true
    }

    $assetsDir = Join-Path $ResourcesPath "ion-dist\assets\v1"
    if (Test-Path -LiteralPath $assetsDir -PathType Container) {
        $jsFiles = Get-ChildItem -LiteralPath $assetsDir -Filter "*.js" -File -ErrorAction SilentlyContinue
        $patched = $false
        foreach ($js in $jsFiles) {
            $txt = [System.IO.File]::ReadAllText($js.FullName)
            if ($txt.Contains('"zh-TW"')) {
                $patched = $true
                break
            }
        }
        if (-not $patched) {
            return $true
        }
    }
    return $false
}

function Do-AutoHeal {
    $claudePath = Find-ClaudePath
    if (-not $claudePath) { return }
    $resourcesPath = Get-ResourcesPath -ClaudePath $claudePath
    if (-not $resourcesPath) { return }

    if (-not (Test-NeedsHeal -ResourcesPath $resourcesPath)) {
        return
    }

    try {
        Do-Install -SilentInstall -NoRestart
        $logDir = Join-Path ${env:LOCALAPPDATA} "Claude-zh-TW"
        if (-not (Test-Path -LiteralPath $logDir)) {
            [System.IO.Directory]::CreateDirectory($logDir) | Out-Null
        }
        $logFile = Join-Path $logDir "autoheal.log"
        $now = (Get-Date).ToString("yyyy-MM-dd HH:mm:ss")
        [System.IO.File]::AppendAllText($logFile, "[$now] 偵測到 Claude 小版本更新，已自動修復繁體中文在地化！`r`n", [System.Text.Encoding]::UTF8)
    } catch {}
}

function Restart-Claude {
    try {
        Stop-Process -Name "claude" -Force -ErrorAction SilentlyContinue
    } catch {}
    Start-Sleep -Seconds 2

    $claudePath = Find-ClaudePath
    if (-not $claudePath) { return }

    # 嘗試透過 AppsFolder 啟動 MSIX
    try {
        [xml]$manifest = Get-Content -LiteralPath (Join-Path $claudePath "AppxManifest.xml") -Raw
        $appId = [string]$manifest.Package.Applications.Application.Id
        $identity = [string]$manifest.Package.Identity.Name
        $folderLeaf = Split-Path -Leaf $claudePath
        if ($folderLeaf -match "__([^_]+)$") {
            $pfn = "$identity`_$($Matches[1])"
            Start-Process "explorer.exe" "shell:AppsFolder\$pfn!$appId" | Out-Null
            Start-Sleep -Seconds 3
            Write-Host "Claude Desktop 已重新啟動！" -ForegroundColor Green
            return
        }
    } catch {}

    $exe = Join-Path $claudePath "app\claude.exe"
    if (Test-Path -LiteralPath $exe) {
        Start-Process "explorer.exe" "`"$exe`"" | Out-Null
        Start-Sleep -Seconds 3
        Write-Host "Claude Desktop 已重新啟動！" -ForegroundColor Green
    }
}

function Print-Banner {
    Write-Host ""
    Write-Host "  ========================================================" -ForegroundColor Cyan
    Write-Host "        Claude Desktop 臺灣正體中文語言包 (zh-TW)        " -ForegroundColor Cyan
    Write-Host "       道地臺灣習慣用語 · 自動守護小版本更新不失效       " -ForegroundColor DarkCyan
    Write-Host "  ========================================================" -ForegroundColor Cyan
    Write-Host ""
}

function Do-Install {
    param([switch]$SilentInstall)

    if (-not $SilentInstall) {
        Print-Banner
        Write-Host "=== 開始安裝繁體中文語言包 ==="
        Write-Host ""
        Write-Host "[1/6] 尋找 Claude Desktop 安裝目錄..."
    }

    $claudePath = Find-ClaudePath
    if (-not $claudePath) {
        throw "未偵測到已安裝的 Claude Desktop！請先安裝 Claude Desktop。"
    }
    $resourcesPath = Get-ResourcesPath -ClaudePath $claudePath
    if (-not $resourcesPath) {
        throw "找不到 resources 目錄: $claudePath\app\resources"
    }

    if (-not $SilentInstall) {
        Write-Host "  發現 Claude 目錄: $claudePath" -ForegroundColor Green
        Write-Host ""
        Write-Host "[2/6] 取得目錄寫入權限..."
    }

    $pathsToGrant = @(
        $resourcesPath,
        (Join-Path $resourcesPath "ion-dist"),
        (Join-Path $resourcesPath "ion-dist\i18n"),
        (Join-Path $resourcesPath "ion-dist\i18n\statsig"),
        (Join-Path $resourcesPath "ion-dist\assets"),
        (Join-Path $resourcesPath "ion-dist\assets\v1")
    )
    foreach ($p in $pathsToGrant) {
        Grant-WriteAccess -Path $p
    }
    $assetsDir = Join-Path $resourcesPath "ion-dist\assets\v1"
    if (Test-Path -LiteralPath $assetsDir -PathType Container) {
        Get-ChildItem -LiteralPath $assetsDir -Filter "*.js" -File -ErrorAction SilentlyContinue |
            ForEach-Object { Grant-WriteAccess -Path $_.FullName }
    }

    if (-not $SilentInstall) {
        Write-Host "  目錄權限解鎖完成" -ForegroundColor Green
        Write-Host ""
        Write-Host "[3/6] 部署臺灣正體中文在地化語系檔案..."
    }

    $localesDir = Join-Path $PSScriptRoot "locales"
    $hasLocalFiles = (Test-Path -LiteralPath (Join-Path $localesDir "ion-dist.json") -PathType Leaf) -and
                     (Test-Path -LiteralPath (Join-Path $localesDir "desktop-shell.json") -PathType Leaf) -and
                     (Test-Path -LiteralPath (Join-Path $localesDir "statsig.json") -PathType Leaf)

    if ($hasLocalFiles) {
        if (-not $SilentInstall) {
            Write-Host "  [來源] 優先載入 locales 目錄語系檔案..." -ForegroundColor Cyan
        }
        Copy-Item -LiteralPath (Join-Path $localesDir "ion-dist.json") -Destination (Join-Path $resourcesPath "ion-dist\i18n\zh-TW.json") -Force
        Copy-Item -LiteralPath (Join-Path $localesDir "ion-dist.json") -Destination (Join-Path $resourcesPath "ion-dist\i18n\zh-Hant.json") -Force
        Copy-Item -LiteralPath (Join-Path $localesDir "desktop-shell.json") -Destination (Join-Path $resourcesPath "zh-TW.json") -Force
        Copy-Item -LiteralPath (Join-Path $localesDir "desktop-shell.json") -Destination (Join-Path $resourcesPath "zh-Hant.json") -Force
        Copy-Item -LiteralPath (Join-Path $localesDir "statsig.json") -Destination (Join-Path $resourcesPath "ion-dist\i18n\statsig\zh-TW.json") -Force
        Copy-Item -LiteralPath (Join-Path $localesDir "statsig.json") -Destination (Join-Path $resourcesPath "ion-dist\i18n\statsig\zh-Hant.json") -Force
    } else {
        if (-not $SilentInstall) {
            Write-Host "  [來源] 載入腳本內建臺灣正體中文資源庫..." -ForegroundColor Cyan
        }
        Decompress-B64GzToFile -Base64 $B64_ION -OutPath (Join-Path $resourcesPath "ion-dist\i18n\zh-TW.json")
        Decompress-B64GzToFile -Base64 $B64_ION -OutPath (Join-Path $resourcesPath "ion-dist\i18n\zh-Hant.json")
        Decompress-B64GzToFile -Base64 $B64_DESKTOP -OutPath (Join-Path $resourcesPath "zh-TW.json")
        Decompress-B64GzToFile -Base64 $B64_DESKTOP -OutPath (Join-Path $resourcesPath "zh-Hant.json")
        Decompress-B64GzToFile -Base64 $B64_STATSIG -OutPath (Join-Path $resourcesPath "ion-dist\i18n\statsig\zh-TW.json")
        Decompress-B64GzToFile -Base64 $B64_STATSIG -OutPath (Join-Path $resourcesPath "ion-dist\i18n\statsig\zh-Hant.json")
    }

    # 寫入 overrides 佔位檔
    Write-Utf8File -Path (Join-Path $resourcesPath "ion-dist\i18n\zh-TW.overrides.json") -Content "{}`n"
    Write-Utf8File -Path (Join-Path $resourcesPath "ion-dist\i18n\zh-Hant.overrides.json") -Content "{}`n"

    if (-not $SilentInstall) {
        Write-Host "  → ion-dist\i18n\zh-TW.json (18,363 條前端介面在地化)" -ForegroundColor Green
        Write-Host "  → zh-TW.json (837 條視窗與系統選單在地化)" -ForegroundColor Green
        Write-Host "  → ion-dist\i18n\statsig\zh-TW.json (模型與功能提示文案)" -ForegroundColor Green
        Write-Host "  → ion-dist\i18n\zh-TW.overrides.json (防止前端 404)" -ForegroundColor Green
        Write-Host ""
        Write-Host "[4/6] 註冊繁體中文語言 (zh-TW)..."
    }

    [void](Patch-JsLanguage -ResourcesPath $resourcesPath -Silent:$SilentInstall)

    if (-not $SilentInstall) {
        Write-Host ""
        Write-Host "[5/6] 更新偏好設定..."
    }
    Update-Config -Locale "zh-TW" -Silent:$SilentInstall

    if (-not $SilentInstall) {
        Write-Host ""
        Write-Host "[6/6] 註冊自動守護排程 (小版本更新不失效)..."
    }
    Register-AutoHealTask -ScriptPath $PSCommandPath

    if (-not $SilentInstall) {
        Write-Host ""
        Write-Host "=========================================" -ForegroundColor Green
        Write-Host "  恭喜！繁體中文語言包已順利安裝完成！  " -ForegroundColor Green
        Write-Host "=========================================" -ForegroundColor Green

        if ($NoRestart) {
            Write-Host "請手動重新啟動 Claude Desktop。"
        } else {
            Write-Host ""
            Restart-Claude
        }
    }
}

function Do-Uninstall {
    Print-Banner
    Write-Host "=== 開始解除安裝繁體中文語言包 ==="
    Write-Host ""

    $claudePath = Find-ClaudePath
    if (-not $claudePath) {
        throw "未偵測到已安裝的 Claude Desktop"
    }
    $resourcesPath = Get-ResourcesPath -ClaudePath $claudePath

    Write-Host "[1/4] 清理語言包檔案..."
    foreach ($path in @(
            (Join-Path $resourcesPath "ion-dist\i18n\zh-TW.json"),
            (Join-Path $resourcesPath "ion-dist\i18n\zh-TW.overrides.json"),
            (Join-Path $resourcesPath "ion-dist\i18n\zh-Hant.json"),
            (Join-Path $resourcesPath "ion-dist\i18n\zh-Hant.overrides.json"),
            (Join-Path $resourcesPath "zh-TW.json"),
            (Join-Path $resourcesPath "zh-Hant.json"),
            (Join-Path $resourcesPath "ion-dist\i18n\statsig\zh-TW.json"),
            (Join-Path $resourcesPath "ion-dist\i18n\statsig\zh-Hant.json")
        )) {
        if (Test-Path -LiteralPath $path -PathType Leaf) {
            Grant-WriteAccess -Path $path
            Remove-Item -LiteralPath $path -Force
        }
    }
    Write-Host "  已移除語言包檔案" -ForegroundColor Green

    Write-Host ""
    Write-Host "[2/4] 還原前端 JS 語言註冊..."
    Unpatch-JsLanguage -ResourcesPath $resourcesPath

    Write-Host ""
    Write-Host "[3/4] 還原預設偏好設定為英文 (en-US)..."
    Update-Config -Locale "en-US"

    Write-Host ""
    Write-Host "[4/4] 移除自動守護排程..."
    Unregister-AutoHealTask

    Write-Host ""
    Write-Host "=== 繁體中文語言包解除安裝完成 ===" -ForegroundColor Green

    if ($NoRestart) {
        Write-Host "請手動重新啟動 Claude Desktop。"
    } else {
        Write-Host ""
        Restart-Claude
    }
}

$scriptArgs = @()
if ($Uninstall) {
    $scriptArgs += "-Uninstall"
}
if ($Install) {
    $scriptArgs += "-Install"
}
if ($AutoHeal) {
    $scriptArgs += "-AutoHeal"
}
if ($Silent) {
    $scriptArgs += "-Silent"
}
if ($NoRestart) {
    $scriptArgs += "-NoRestart"
}
if ($PauseAtEnd) {
    $scriptArgs += "-PauseAtEnd"
}

Ensure-Administrator -Arguments $scriptArgs

try {
    if ($AutoHeal) {
        Do-AutoHeal
        exit 0
    }
    elseif ($Uninstall) {
        Do-Uninstall
    }
    elseif ($Install) {
        Do-Install
    }
    else {
        Print-Banner
        Write-Host "請選擇您要執行的操作：" -ForegroundColor Yellow
        Write-Host "  [1] 安裝繁體中文語言包 (zh-TW)" -ForegroundColor Cyan
        Write-Host "  [2] 解除安裝繁體中文語言包 (還原為英文原版)" -ForegroundColor Cyan
        Write-Host "  [0] 離開"
        Write-Host ""
        $choice = Read-Host "請輸入選項編號 [預設: 1]"
        if ($choice -eq "2") {
            Do-Uninstall
        } elseif ($choice -eq "0") {
            exit 0
        } else {
            Do-Install
        }
    }
}
catch {
    if (-not $Silent) {
        Write-Host ""
        Write-Host "[錯誤] $($_.Exception.Message)" -ForegroundColor Red
    }
}
finally {
    Wait-BeforeExit
}
